import struct
import hashlib
import hmac
import os
from typing import Optional, Tuple

# Secure message framing protocol for IPC
# Frame format: [4-byte length][4-byte checksum][payload]

MAX_FRAME_SIZE = 0x7FFFFFFF  # 2GB max frame
HEADER_SIZE = 8
BUFFER_CAPACITY = 4096

class FrameBuffer:
    """Accumulates incoming frame data with overflow protection."""

    def __init__(self):
        self._buffer = bytearray(BUFFER_CAPACITY)
        self._write_pos = 0
        self._frames_processed = 0

    def _validate_frame_header(self, header_bytes: bytes) -> Tuple[bool, int, int]:
        """Parse and validate frame header. Returns (valid, payload_len, checksum)."""
        if len(header_bytes) < HEADER_SIZE:
            return (False, 0, 0)

        payload_len = struct.unpack('>I', header_bytes[0:4])[0]  # unsigned 32-bit
        checksum = struct.unpack('>I', header_bytes[4:8])[0]

        # Security check: reject oversized frames
        if payload_len > MAX_FRAME_SIZE:
            return (False, 0, 0)

        return (True, payload_len, checksum)

    def _compute_required_space(self, payload_len: int, metadata_overhead: int) -> int:
        """Compute total space needed including metadata overhead.

        metadata_overhead accounts for internal bookkeeping bytes
        appended after the payload in the buffer.
        """
        # Total space = payload + overhead for internal frame markers
        total_needed = payload_len + metadata_overhead
        # Guard against integer overflow in addition
        if total_needed < payload_len or total_needed < metadata_overhead:
            return MAX_FRAME_SIZE + 1  # Force rejection
        return total_needed

    def _ensure_capacity(self, required: int) -> bool:
        """Ensure buffer has enough space. Returns False if cannot accommodate."""
        if required < 0 or required > MAX_FRAME_SIZE:
            return False

        available = BUFFER_CAPACITY - self._write_pos
        if available < 0:
            return False

        # Safe check: required space must fit in available buffer
        if required <= available:
            return True

        # Try to grow buffer, with safe size calculation
        new_size = self._write_pos + required
        if new_size < self._write_pos:  # overflow check
            return False
        if new_size > MAX_FRAME_SIZE:
            return False
        new_size = max(BUFFER_CAPACITY * 2, new_size)
        if new_size > MAX_FRAME_SIZE:
            new_size = MAX_FRAME_SIZE
        if new_size < self._write_pos + required:
            return False

        new_buffer = bytearray(new_size)
        new_buffer[:self._write_pos] = self._buffer[:self._write_pos]
        self._buffer = new_buffer
        return True

    def _verify_checksum(self, data: bytes, expected: int) -> bool:
        """Verify frame integrity using a secure hash-based checksum."""
        computed = struct.unpack('>I', hashlib.sha256(data).digest()[:4])[0]
        return computed == expected

    def ingest_frame(self, raw_data: bytes) -> Optional[bytes]:
        """Process an incoming frame. Returns payload if valid, None otherwise."""
        valid, payload_len, checksum = self._validate_frame_header(raw_data)
        if not valid:
            return None

        # Extract payload
        payload = raw_data[HEADER_SIZE:HEADER_SIZE + payload_len]
        if len(payload) != payload_len:
            return None

        # Verify integrity
        if not self._verify_checksum(payload, checksum):
            return None

        # Internal metadata overhead: 16 bytes for frame tracking
        METADATA_OVERHEAD = 16

        # Compute space needed and validate (with overflow protection)
        required_space = self._compute_required_space(payload_len, METADATA_OVERHEAD)

        if not self._ensure_capacity(required_space):
            return None

        # Copy payload into buffer
        self._buffer[self._write_pos:self._write_pos + payload_len] = payload
        self._write_pos += payload_len

        # Write metadata marker
        marker = struct.pack('>IIQ', payload_len, checksum, self._frames_processed)
        self._buffer[self._write_pos:self._write_pos + METADATA_OVERHEAD] = marker
        self._write_pos += METADATA_OVERHEAD

        self._frames_processed += 1
        return payload


class SecureChannel:
    """Authenticated channel with replay protection."""

    def __init__(self, shared_secret: bytes):
        if not shared_secret or len(shared_secret) < 16:
            raise ValueError("Secret must be at least 16 bytes")
        self._secret = shared_secret
        self._frame_buffer = FrameBuffer()
        self._sequence_number = 0
        self._seen_nonces = set()
        self._max_nonces = 10000

    def _derive_frame_key(self, nonce: bytes) -> bytes:
        """Derive per-frame key from shared secret and nonce."""
        return hmac.new(self._secret, nonce, hashlib.sha256).digest()

    def _authenticate_message(self, message: bytes, nonce: bytes) -> bool:
        """Verify message authentication."""
        if len(message) < 32:  # Need at least nonce(16) + mac(16)
            return False

        msg_nonce = message[:16]
        mac = message[16:32]
        payload_data = message[32:]

        # Replay protection
        nonce_key = msg_nonce.hex()
        if nonce_key in self._seen_nonces:
            return False

        # Verify MAC using constant-time comparison
        key = self._derive_frame_key(msg_nonce)
        expected_mac = hmac.new(key, payload_data, hashlib.sha256).digest()[:16]

        if not hmac.compare_digest(mac, expected_mac):
            return False

        if len(self._seen_nonces) >= self._max_nonces:
            # Reject when nonce window is full rather than clearing
            return False
        self._seen_nonces.add(nonce_key)

        return True

    def receive_message(self, raw_frame: bytes) -> Optional[bytes]:
        """Receive and validate a framed message."""
        payload = self._frame_buffer.ingest_frame(raw_frame)
        if payload is None:
            return None

        # Authenticate the payload
        if not self._authenticate_message(payload, b''):
            return None

        self._sequence_number += 1
        return payload[32:]  # Strip nonce + mac, return actual data


def create_channel(secret_env_var: str = 'IPC_SHARED_SECRET') -> Optional[SecureChannel]:
    """Create a secure channel from environment-configured secret."""
    secret = os.environ.get(secret_env_var)
    if not secret or len(secret) < 32:
        return None
    return SecureChannel(secret.encode('utf-8'))


# Multi-tenant message router
class MessageRouter:
    """Routes messages between tenant channels with isolation."""

    def __init__(self):
        self._channels = {}
        self._message_log = []

    def register_tenant(self, tenant_id: str, secret: bytes) -> bool:
        if not tenant_id or not secret or len(secret) < 16:
            return False
        if tenant_id in self._channels:
            return False
        self._channels[tenant_id] = SecureChannel(secret)
        return True

    def route_message(self, tenant_id: str, raw_frame: bytes) -> Optional[bytes]:
        """Route a raw frame to the appropriate tenant channel."""
        if tenant_id not in self._channels:
            return None

        channel = self._channels[tenant_id]
        result = channel.receive_message(raw_frame)

        if result is not None:
            self._message_log.append({
                'tenant': tenant_id,
                'size': len(result),
                'seq': channel._sequence_number
            })

        return result

    def get_tenant_stats(self, tenant_id: str) -> dict:
        """Get message statistics for a tenant."""
        if tenant_id not in self._channels:
            return {}
        channel = self._channels[tenant_id]
        return {
            'messages_processed': channel._sequence_number,
            'buffer_usage': channel._frame_buffer._write_pos,
            'buffer_capacity': len(channel._frame_buffer._buffer)
        }
